/// 预警域的全部文字。按语言取实现。
pub fn intel(language: AppLanguage) -> &'static dyn IntelStrings {
    match language {
        AppLanguage::En => &IntelStringsEn,
        AppLanguage::Zh => &IntelStringsZh,
        AppLanguage::Ru => &IntelStringsRu,
        AppLanguage::Ja => &IntelStringsJa,
        AppLanguage::Ko => &IntelStringsKo,
        AppLanguage::Fr => &IntelStringsFr,
        AppLanguage::De => &IntelStringsDe,
        AppLanguage::Es => &IntelStringsEs,
    }
}
